@using sv_c1d338134b1c49ea8e1a8c1627c9a791.Services

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p class="channel-desc">@ChannelDescription</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @if (HasMoreMessages)
        {
            <button class="load-more-btn" @onclick="OnLoadMore">Load older messages</button>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadReplyCount="GetThreadReplyCount(message.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input" @bind="newMessageText" @bind:event="oninput"
                  placeholder="Type a message..." @onkeydown="HandleKeyDown"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">Send</button>
    </div>
</div>

@code {
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string newMessageText = "";

    private int GetThreadReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;
        var text = newMessageText;
        newMessageText = "";
        await OnSendMessage.InvokeAsync(text);
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private Task HandleScroll()
    {
        // Scroll-to-top detection would require JS interop for precise scroll position.
        // The "Load older messages" button provides the fallback UX.
        return Task.CompletedTask;
    }
}

